<?php declare(strict_types=1); namespace Annam; $title='Kitchen overview';$subtitle=date('l, j F').' · '.$store->name();$body_class='owner-dashboard';$actions='<a class="o-btn o-btn-primary" href="/manage/dishes/new/?kind=scheduled"><svg class="o-ic"><use href="#o-plus"/></svg>Add a dish</a>';
$sales=(new Reports($store))->sales();$recent=$store->db->rows('SELECT * FROM orders_order WHERE tenant_id=? ORDER BY placed_at DESC LIMIT 6',[$store->id()]);
$on=count(array_filter($items,fn($i)=>$i['active']));$shop=count(array_filter($items,fn($i)=>$i['active']&&$i['fulfilment']==='courier'));$missing=count(array_filter($items,fn($i)=>$i['active']&&!$i['image']));$todayCount=(int)$store->db->one('SELECT COUNT(*) AS n FROM orders_order WHERE tenant_id=? AND placed_at>=? AND placed_at<?',[$store->id(),$date,date('Y-m-d',strtotime($date.' +1 day'))])['n'];$weekCount=(int)$store->db->one('SELECT COUNT(*) AS n FROM orders_order WHERE tenant_id=? AND placed_at>=?',[$store->id(),date('Y-m-d',strtotime('-6 days'))])['n'];
$stats=[['Dishes on sale',$on,'/manage/dishes/?status=1',count($items)],['Hidden / sold out',count($items)-$on,'/manage/dishes/?status=0',null],['Shop items',$shop,'/manage/dishes/?kind=courier',null],['Orders today',$todayCount,'/manage/orders/',null],['Orders this week',$weekCount,'/manage/orders/',null],['Categories',count(array_filter($store->categories(),fn($c)=>$c['active'])),'/manage/categories/',null]];?>
<section class="o-card"><h2>Today’s sales · <?= money($sales['order_value']) ?></h2><p><?= e($sales['order_count']) ?> orders · Paid order value <?= money($sales['paid_order_value']) ?> · Updated <?= date('g:i A') ?></p><a class="o-btn o-btn-primary" href="/manage/reports/">View live sales &amp; product quantities →</a></section>
<section class="od-stats" aria-label="Kitchen statistics"><?php foreach($stats as [$label,$value,$url,$of]):?><a class="od-stat" href="<?= e($url) ?>"><span class="od-stat-top"><span class="od-stat-label"><?= e($label) ?></span><svg class="o-ic"><use href="#o-dish"/></svg></span><strong><?= e($value) ?><?php if($of!==null):?><small>/ <?= e($of) ?></small><?php endif;?></strong></a><?php endforeach;?></section>
<?php if($missing):?><a class="o-callout od-photo-notice" href="/manage/dishes/?status=1"><svg class="o-ic"><use href="#o-image"/></svg><span><b><?= e($missing) ?> dishes on sale without a photo.</b> Add photos to help customers choose.</span><span>→</span></a><?php endif;?>
<section class="od-menu" aria-labelledby="od-menu-title"><header class="od-section-head"><div><h2 id="od-menu-title">Today’s menu</h2><p>Your meals, dishes and order cutoffs at a glance.</p></div><a class="od-text-link" href="/manage/dishes/?kind=scheduled">Edit menu →</a></header><div class="od-meals"><?php foreach($menus as $m):?><article class="od-meal"><header class="od-meal-head"><span class="od-meal-icon"><svg class="o-ic"><use href="#o-dish"/></svg></span><div><h3><?= e($m['slot']['label']) ?></h3><span>Orders close <?= e(date('g:i A',strtotime($m['slot']['order_cutoff']))) ?></span></div><span class="od-item-count"><?= count($m['items']) ?> items</span></header><?php if($m['items']):?><ul class="od-dishes"><?php foreach($m['items'] as $i):?><li><a href="/manage/dishes/<?= e($i['id']) ?>/"><span><?= e($i['name']) ?></span><strong><?= money($i['effective_price']??$i['price']) ?></strong></a></li><?php endforeach;?></ul><?php else:?><div class="od-meal-empty"><p>No dishes scheduled today.</p><a href="/manage/dishes/menu/?slot_id=<?= e($m['slot']['id']) ?>&date=<?= e($date) ?>">Add dishes to this meal →</a></div><?php endif;?></article><?php endforeach;?></div></section>
<div class="od-bottom"><section class="od-panel"><header class="od-section-head"><div><h2>Latest orders</h2><p>Recent bookings across your kitchen.</p></div><a class="od-text-link" href="/manage/orders/">All orders →</a></header><?php if($recent):?><ul class="od-orders"><?php foreach($recent as $o):?><li><a href="/manage/orders/<?= e($o['id']) ?>/"><span class="od-order-icon"><svg class="o-ic"><use href="#o-bag"/></svg></span><span class="od-order-customer"><strong><?= e($o['order_no']) ?></strong><small><?= e($o['placed_at']) ?></small></span><span class="o-pill o-pill-<?= e($o['status']) ?>"><?= e(ucfirst($o['status'])) ?></span><strong class="o-money"><?= money($o['total']) ?></strong></a></li><?php endforeach;?></ul><?php else:?><div class="od-orders-empty"><span class="od-empty-icon"><svg class="o-ic"><use href="#o-bag"/></svg></span><div><h3>Ready for your next order</h3><p>New orders will appear here. You can also enter a booking in the billing portal.</p><a href="/manage/orders/new/">Open billing portal →</a></div></div><?php endif;?></section><section class="od-panel od-tools"><header class="od-section-head"><div><h2>Quick actions</h2><p>The tools you use every day.</p></div></header><div class="od-tool-grid"><?php foreach([['/billing/','Billing portal','Bookings & invoices'],['/manage/whatsapp/','WhatsApp inbox','Customer conversations'],['/manage/banners/new/','New offer banner','Offers & specials'],['/manage/settings/','Store settings','Contact & store details']] as [$url,$label,$help]):?><a href="<?= e($url) ?>"><svg class="o-ic"><use href="#o-page"/></svg><span><strong><?= e($label) ?></strong><small><?= e($help) ?></small></span><span>→</span></a><?php endforeach;?></div></section></div>
